<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {useRoute} from 'vue-router';
import {api} from '@/lib/api';
import {useContentStore,type ContentMetadata} from '@/stores/content';
import {useConfirmStore} from '@/stores/confirm';
import {useUnsavedGuard} from '@/lib/useUnsavedGuard';
import LineChart from '@/components/ui/LineChart.vue';
import TrackImage from '@/components/TrackImage.vue';
const route=useRoute(),content=useContentStore(),confirm=useConfirmStore();
const kind=computed(()=>String(route.params.kind)),key=computed(()=>String(route.params.key)),layout=computed(()=>String(route.query.layout??''));
const item=computed(()=>kind.value==='car'?content.carByKey(key.value):kind.value==='track'?content.trackByKey(key.value,layout.value):content.weathers.find(w=>w.key===key.value));
const metadata=ref<ContentMetadata|null>(null),saved=ref(''),error=ref(''),message=ref(''),busy=ref(false),tags=ref('');
const curves=ref<{power:number[];torque:number[];labels:number[]}|null>(null);
const chartSeries=computed(()=>curves.value?[{name:'Power',color:'var(--color-accent)',values:curves.value.power??[],unit:' bhp'},{name:'Torque',color:'var(--color-warn)',values:curves.value.torque??[],unit:' Nm'}].filter(s=>s.values.some(v=>v>0)):[]);
const usage=ref<{event_id:number;session_id:number|null;name:string;lifecycle:string;pending_queue_items:number}[]>([]);
const endpoint=()=>`/api/content/metadata/${kind.value}/${encodeURIComponent(key.value)}?layout=${encodeURIComponent(layout.value)}`;
const dirty=computed(()=>!!metadata.value&&(JSON.stringify(metadata.value)!==saved.value||tags.value!==metadata.value.tags.join(', ')));
useUnsavedGuard(()=>dirty.value);
async function load(){error.value='';try{await content.load();const result=await api.get<{metadata:ContentMetadata;usage:typeof usage.value}>(endpoint());metadata.value=result.metadata;usage.value=result.usage;tags.value=result.metadata.tags.join(', ');saved.value=JSON.stringify(result.metadata);curves.value=null;if(kind.value==='car')curves.value=await api.get(`/api/car/${encodeURIComponent(key.value)}`)}catch(e){error.value=String(e)}}
async function save(){if(!metadata.value)return;busy.value=true;error.value='';try{metadata.value.tags=tags.value.split(',').map(t=>t.trim()).filter(Boolean);metadata.value=await api.put<ContentMetadata>(endpoint(),metadata.value);saved.value=JSON.stringify(metadata.value);tags.value=metadata.value.tags.join(', ');await content.loadMetadata();message.value='Library details saved.'}catch(e){error.value=String(e)}finally{busy.value=false}}
async function remove(){if(!await confirm.ask({title:`Delete ${item.value?.name||key.value} from disk?`,message:`Permanently remove this ${kind.value}${kind.value==='track'?' and every layout':''} from the Assetto Corsa installation.`,detail:'Saved setup dependencies and running servers block deletion. Archive hides an item from selection and keeps its files.',confirmLabel:'Delete from disk',tone:'danger'}))return;busy.value=true;try{if(kind.value==='car')await content.deleteCar(key.value);else if(kind.value==='track')await content.deleteTrack(key.value);else await content.deleteWeather(key.value);message.value='Deleted from disk. Local notes remain available.'}catch(e){error.value=String(e)}finally{busy.value=false}}
watch(()=>route.fullPath,load);onMounted(load);
</script>
<template><header class="pitlane-heading"><div><span class="pitlane-eyebrow">Garage / Cars & tracks / {{ kind }}</span><h1>{{ metadata?.display_name || item?.name || key }}</h1><p>{{ layout || 'Base content' }} · {{ metadata?.archived?'Archived · existing setups can still use this':'Available in the library' }}</p></div><RouterLink to="/garage/content" class="pitlane-button">← Cars & tracks</RouterLink></header><div v-if="error" class="pitlane-error" role="alert">{{ error }} <button @click="load">Reload</button></div><p v-if="message" role="status">{{ message }}</p><div v-if="metadata" class="content-detail-grid"><section class="pitlane-card"><TrackImage v-if="kind==='track'" :track-key="key" :config="layout" class="h-64 rounded-lg mb-6"/><img v-if="kind==='car'" :src="`/api/car/image/${encodeURIComponent(key)}/${encodeURIComponent(content.carByKey(key)?.skins?.[0]?.key??'')}`" alt="" class="w-full h-64 object-contain"/><h2>Installed details</h2><p class="font-mono text-xs mt-3">{{ key }}{{ layout ? ' / '+layout : '' }}</p><p v-if="!item">Content is currently unavailable. Your local metadata is preserved.</p><dl v-if="item" class="content-facts"><template v-for="(value,field) in item" :key="field"><template v-if="['brand','class','country','city','length','width','pitboxes','version','author','description','desc'].includes(String(field))&&value"><dt>{{ field }}</dt><dd>{{ value }}</dd></template></template></dl><template v-if="kind==='track'"><h3 class="mt-6">Layouts</h3><RouterLink v-for="track in content.tracks.filter(t=>t.key===key)" :key="track.config??''" :to="`/garage/content/track/${encodeURIComponent(key)}?layout=${encodeURIComponent(track.config??'')}`" class="pitlane-button mt-3">{{ track.name }} · {{ track.config || 'Default' }}</RouterLink></template><template v-if="kind==='car'"><h3 class="mt-6">Specifications</h3><dl class="content-facts"><template v-for="(value,label) in content.carByKey(key)?.specs" :key="label"><dt>{{ label }}</dt><dd>{{ value }}</dd></template></dl><h3 class="mt-6">Power &amp; torque</h3><LineChart v-if="chartSeries.length" :series="chartSeries" :labels="curves?.labels??[]" x-label="RPM"/><p v-else>No dyno data supplied with this car.</p><h3 class="mt-6">Skins</h3><div class="flex flex-wrap gap-2 mt-3"><span v-for="skin in content.carByKey(key)?.skins" :key="skin.key" class="pitlane-button">{{ skin.name||skin.key }}</span></div></template><RouterLink to="/garage/content?imports=1" class="pitlane-button mt-6">Import or replace content</RouterLink></section><div class="pitlane-stack"><form class="pitlane-card pitlane-stack" @submit.prevent="save"><h2>Your library details</h2><p>Local details survive rescans. Original content files stay with the installation.</p><label class="pitlane-field">Display name<input v-model="metadata.display_name" maxlength="160" :placeholder="item?.name||key"/></label><label class="pitlane-field">Tags, separated by commas<input v-model="tags"/></label><label class="pitlane-field">Notes<textarea v-model="metadata.notes" maxlength="10000" rows="5"/></label><label class="flex gap-3"><input v-model="metadata.archived" type="checkbox"/>Archive from new selections</label><button class="pitlane-button primary" :disabled="busy||!dirty">Save library details</button></form><section class="pitlane-card"><h2>Used by {{ usage.length }} saved setups</h2><p v-if="!usage.length">No saved setup references this exact content.</p><RouterLink v-for="u in usage" :key="u.event_id" :to="u.session_id?`/sessions/${u.session_id}`:'/events'" class="block py-3 border-b border-line">{{ u.name||`Setup ${u.event_id}` }} · {{ u.lifecycle }}<small v-if="u.pending_queue_items"> · {{ u.pending_queue_items }} pending queue entries</small></RouterLink><RouterLink to="/garage/recovery" class="pitlane-button mt-5">Recent changes & undo</RouterLink></section><section class="pitlane-card"><h2>Remove installed files</h2><p>Disk deletion is permanent. Archive is reversible and preserves existing sessions.</p><button class="pitlane-button mt-4" :disabled="busy||usage.length>0" @click="remove">Delete {{ kind }} from disk</button></section></div></div></template>
<style scoped>.content-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.content-facts{display:grid;grid-template-columns:auto 1fr;gap:12px;margin-top:22px;font-size:14px}.content-facts dt{text-transform:capitalize;color:var(--color-muted)}.content-facts dd{overflow-wrap:anywhere}@media(max-width:800px){.content-detail-grid{grid-template-columns:1fr}}</style>
